class Solution {
    public int countConsistentStrings(String allowed,String[] words){
        boolean[] valid=new boolean[26];
        for(char letter:allowed.toCharArray())valid[letter-'a']=true;
        int answer=0;
        for(String word:words){
            boolean consistent=true;
            for(char letter:word.toCharArray())if(!valid[letter-'a']){
                consistent=false;
                break;
            }
            if(consistent)answer++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countConsistentStrings(allowed:String,words:Array<String>):Int{
        val valid=BooleanArray(26);
        for(letter in allowed)valid[letter-'a']=true;
        return words.count{
            word->word.all{
                valid[it-'a']
            }
        }
    }
}

